#!/usr/bin/env bash
# INTERIM (gc-462084/gc-462797): unwedge control-dispatcher port-0 stall. The serve-path
# curated work-query exec env carries GC_STORE_*/GC_RIG but OMITS GC_DOLT_PORT, so bd
# --sandbox resolves Dolt at :0. This script (set as the agent work_query) inherits that
# curated env and just adds the port, then runs the verbatim compiled control-ready query.
# REMOVE this + the city.toml work_query override once dispatch_runtime.go:365 deploys.
export GC_DOLT_PORT=29620
export BEADS_DOLT_SERVER_PORT=29620
BD_EXPORT_AUTO=false GC_CONTROL_TARGET='core.control-dispatcher' GC_CONTROL_SESSION_NAME='core__control-dispatcher' GC_CONTROL_BARE_TARGET='control-dispatcher' sh -c 'set -e; tmp=$(mktemp); seen="$tmp.seen"; err="$tmp.err"; : > "$seen"; trap "rm -f \"$tmp\" \"$seen\" \"$err\"" EXIT; emit_ready() { r=$("$@" 2>"$err") || { status=$?; [ -n "$r" ] && printf "%s\n" "$r" >&2; cat "$err" >&2; return "$status"; }; [ -n "$r" ] && [ "$r" != "[]" ] && printf "%s\n" "$r" >> "$tmp"; return 0; }; assignee_ready() { cand="$1"; [ -z "$cand" ] && return 0; if grep -Fxq "$cand" "$seen"; then return 0; fi; printf "%s\n" "$cand" >> "$seen"; emit_ready bd --readonly --sandbox ready --assignee="$cand" --exclude-type=epic --json --limit=20; }; routed_ready() { route="$1"; [ -z "$route" ] && return 0; emit_ready bd --readonly --sandbox ready --metadata-field "gc.run_target=$route" --unassigned --exclude-type=epic --json --sort oldest --limit=20; emit_ready bd --readonly --sandbox ready --metadata-field "gc.routed_to=$route" --unassigned --exclude-type=epic --json --sort oldest --limit=20; }; for id in "$GC_CONTROL_SESSION_NAME" "$GC_SESSION_NAME" "$GC_ALIAS" "$GC_CONTROL_TARGET" "$GC_SESSION_ID"; do [ -z "$id" ] && continue; legacy=""; case "$id" in *control-dispatcher) legacy="${id%control-dispatcher}workflow-control";; esac; for cand in "$id" "$legacy"; do [ -z "$cand" ] && continue; assignee_ready "$cand"; done; done; routed_ready "$GC_CONTROL_TARGET"; routed_ready "${GC_CONTROL_LEGACY_TARGET:-}"; routed_ready "${GC_CONTROL_BARE_TARGET:-}"; if [ -s "$tmp" ]; then jq -s "reduce add[] as \$item ([]; if ((\$item.metadata // {})[\"gc.instantiating\"] // \"\") != \"\" then . elif any(.[]; .id == \$item.id) then . else . + [\$item] end)" "$tmp"; else printf "[]"; fi'
